import heapq

def cheapest_route(n, roads, src, dst):
    near = [[] for _ in range(n)]
    for a, b, cost in roads:
        near[a].append((b, cost))
        near[b].append((a, cost))

    def best_from(s):
        best = [None] * n
        best[s] = (0, 0)
        heap = [(0, 0, s)]
        while heap:
            c, k, u = heapq.heappop(heap)
            if (c, k) > best[u]:
                continue
            for v, w in near[u]:
                cand = (c + w, k + 1)
                if best[v] is None or cand < best[v]:
                    best[v] = cand
                    heapq.heappush(heap, (c + w, k + 1, v))
        return best

    fwd, back = best_from(src), best_from(dst)
    if fwd[dst] is None:
        return []
    cost, legs = fwd[dst]
    route, u = [src], src
    while u != dst:
        u = min(v for v, w in near[u] if back[v] is not None
                and fwd[u][0] + w + back[v][0] == cost and fwd[u][1] + 1 + back[v][1] == legs)
        route.append(u)
    return route

